19,"olid":"OL20129837W","editionTitle":"The Testaments","editionOlid":"OL27306829M","isbn10":null,"isbn13":"9780385543781","publisher":"Nan A. Talese/Doubleday","language":null,"correctLanguage":true},{"productionWorkId":208,"testWorkId":921100208,"testEditionId":921200208,"authorId":921300127,"author":"Octavia E. Butler","title":"Parable of the Sower","year":1993,"olid":"OL35623W","editionTitle":"Parable of the Sower: A Novel","editionOlid":"OL27288938M","isbn10":"1609807197","isbn13":"9781609807191","publisher":"Seven Stories Press","language":"eng","correctLanguage":false},{"productionWorkId":2600,"testWorkId":921102600,"testEditionId":921202600,"authorId":921300008,"author":"Margaret Atwood","title":"Oryx and Crake","year":2003,"olid":"OL675722W","editionTitle":"Oryx and Crake","editionOlid":"OL39470791M","isbn10":"0385721676","isbn13":"9780385721677","publisher":"Anchor Books","language":"eng","correctLanguage":false},{"productionWorkId":2717,"testWorkId":921102717,"testEditionId":921202876,"authorId":921301307,"author":"Neal Shusterman","title":"Scythe","year":2016,"olid":"OL17876096W","editionTitle":"Scythe","editionOlid":"OL46932981M","isbn10":"1481485261","isbn13":"9781481485265","publisher":"Simon & Schuster Export Editions","language":"eng","correctLanguage":false},{"productionWorkId":2718,"testWorkId":921102718,"testEditionId":921202877,"authorId":921300172,"author":"Kazuo Ishiguro","title":"Never Let Me Go","year":2005,"olid":"OL59038W","editionTitle":"Never Let Me Go","editionOlid":"OL16198255M","isbn10":"1400078776","isbn13":"9781400078776","publisher":"Vintage International","language":"eng","correctLanguage":false},{"productionWorkId":2724,"testWorkId":921102724,"testEditionId":921202883,"authorId":921301307,"author":"Neal Shusterman","title":"Unwind","year":2007,"olid":"OL1954412W","editionTitle":"Unwind","editionOlid":"OL11758843M","isbn10":"1416912045","isbn13":"9781416912040","publisher":"Simon & Schuster Children's Publishing","language":"eng","correctLanguage":false},{"productionWorkId":2846,"testWorkId":921102846,"testEditionId":921203005,"authorId":921300008,"author":"Margaret Atwood","title":"The Year of the Flood","year":2009,"olid":"OL675774W","editionTitle":"The Year of the Flood","editionOlid":"OL36612602M","isbn10":"1408461420","isbn13":"9781408461426","publisher":"Windsor","language":"eng","correctLanguage":false},{"productionWorkId":4316,"testWorkId":921104316,"testEditionId":921204475,"authorId":921302243,"author":"Martha Wells","title":"All Systems Red","year":2017,"olid":"OL17914663W","editionTitle":"All Systems Red: The Murderbot Diaries","editionOlid":"OL26500848M","isbn10":null,"isbn13":"9780765397539","publisher":"Tor","language":"eng","correctLanguage":false}]$plan$::jsonb) as p("productionWorkId" bigint,"testWorkId" bigint,"testEditionId" bigint,"authorId" bigint,author text,title text,year integer,olid text,"editionTitle" text,"editionOlid" text,isbn10 text,isbn13 text,publisher text,language text,"correctLanguage" boolean);
create temporary table fantasy_before as select 'authors' as kind,count(*) as n,md5(coalesce(string_agg(to_jsonb(a)::text,'|' order by id),'')) as digest from public.authors a where id not in(select "authorId" from fantasy_plan )
union all select 'works',count(*),md5(coalesce(string_agg(to_jsonb(w)::text,'|' order by id),'')) from public.works w where id not in(select "testWorkId" from fantasy_plan)
union all select 'editions',count(*),md5(coalesce(string_agg(to_jsonb(e)::text,'|' order by id),'')) from public.editions e where id not in(select "testEditionId" from fantasy_plan);
do $$ begin
 if (select count(*) from fantasy_plan)<>13 then raise exception 'Wrong scope'; end if;
 if exists(select 1 from fantasy_plan p join public.authors a on a.id=p."authorId" where a.name is distinct from p.author) then raise exception 'Author ID collision'; end if;
 if exists(select 1 from fantasy_plan p join public.authors a on lower(a.name)=lower(p.author) where a.id<>p."authorId") then raise exception 'Reuse author instead of duplicating'; end if;
 if exists(select 1 from fantasy_plan p join public.works w on w.id=p."testWorkId" or w.open_library_id=p.olid where w.id<>p."testWorkId" or w.title is distinct from p.title or w.open_library_id is distinct from p.olid or w.author_id is distinct from p."authorId") then raise exception 'Work identity collision'; end if;
 if exists(select 1 from fantasy_plan p join public.editions e on e.id=p."testEditionId" or e.isbn_13=p.isbn13 or e.open_library_edition_id=p."editionOlid" where e.id<>p."testEditionId" or e.work_id<>p."testWorkId" or e.title is distinct from p."editionTitle" or e.isbn_13 is distinct from p.isbn13 or e.open_library_edition_id is distinct from p."editionOlid" or (e.language is distinct from p.language and not(p."correctLanguage" and e.language='eng'))) then raise exception 'Edition identity collision'; end if;
end $$;
create temporary table fantasy_receipt(kind text,id bigint);
with added as (insert into public.authors(id,name) select distinct p."authorId",p.author from fantasy_plan p where not exists(select 1 from public.authors a where a.id=p."authorId") returning id) insert into fantasy_receipt select 'author_created',id from added;
with added as (insert into public.works(id,title,author_id,first_publish_year,open_library_id,source_type) select distinct p."testWorkId",p.title,p."authorId",p.year,p.olid,'open_library' from fantasy_plan p where not exists(select 1 from public.works w where w.id=p."testWorkId") returning id) insert into fantasy_receipt select 'work_created',id from added;
with added as (insert into public.editions(id,work_id,title,language,open_library_edition_id,isbn_10,isbn_13,publisher) select p."testEditionId",p."testWorkId",p."editionTitle",p.language,p."editionOlid",p.isbn10,p.isbn13,p.publisher from fantasy_plan p where not exists(select 1 from public.editions e where e.id=p."testEditionId") returning id) insert into fantasy_receipt select 'edition_created',id from added;
with changed as (update public.editions e set language='eng' from fantasy_plan p where e.id=p."testEditionId" and p."correctLanguage" and e.language is null returning e.id) insert into fantasy_receipt select 'language_null_to_eng',id from changed;
do $$ begin
 if exists(select 1 from fantasy_plan p left join public.editions e on e.id=p."testEditionId" where e.language is distinct from (case when p."correctLanguage" then 'eng' else p.language end) or e.work_id is distinct from p."testWorkId") then raise exception 'Postcondition failed'; end if;
 if exists(select * from fantasy_before except (select 'authors',count(*),md5(coalesce(string_agg(to_jsonb(a)::text,'|' order by id),'')) from public.authors a where id not in(select "authorId" from fantasy_plan )
 union all select 'works',count(*),md5(coalesce(string_agg(to_jsonb(w)::text,'|' order by id),'')) from public.works w where id not in(select "testWorkId" from fantasy_plan)
 union all select 'editions',count(*),md5(coalesce(string_agg(to_jsonb(e)::text,'|' order by id),'')) from public.editions e where id not in(select "testEditionId" from fantasy_plan))) then raise exception 'Existing catalogue changed'; end if;
end $$;
select jsonb_build_object('target','hlvujbrmfdlrfxdjwsmb','counts',(select jsonb_object_agg(kind,n) from(select kind,count(*) n from fantasy_receipt group by kind)t),'existing_catalogue_unchanged',true,'editions',(select jsonb_agg(jsonb_build_object('productionWorkId',p."productionWorkId",'workId',e.work_id,'editionId',e.id,'title',e.title,'isbn13',e.isbn_13,'language',e.language,'olid',e.open_library_edition_id) order by p."productionWorkId") from fantasy_plan p join public.editions e on e.id=p."testEditionId"),'receipt',(select jsonb_agg(to_jsonb(r)) from fantasy_receipt r)) as verification;
rollback;
